import{_ as s,a as t,b as n,c as r}from"./chunks/solar-solo-ports.BXO9gIDw.js";import{_ as i,o as a,c as o,a3 as u}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse(`{"title":"Solaire – Onduleurs et batteries empilables","description":"Modules SVG neutres dotés de points de connexion affleurants, d'affichages textuels et de ports de flux de données librement assignables.","frontmatter":{"title":"Solaire – Onduleurs et batteries empilables","description":"Modules SVG neutres dotés de points de connexion affleurants, d'affichages textuels et de ports de flux de données librement assignables."},"headers":[],"relativePath":"fr/projects/grafik-visual-studio/solar.md","filePath":"fr/projects/grafik-visual-studio/solar.md","lastUpdated":1793126673000}`),l={name:"fr/projects/grafik-visual-studio/solar.md"};function d(p,e,c,g,m,f){return a(),o("div",null,[...e[0]||(e[0]=[u('<h1 id="solar" tabindex="-1">Solaire <a class="header-anchor" href="#solar" aria-label="Permalink to &quot;Solaire {#solar}&quot;">​</a></h1><p><strong>Solar 0.1.3</strong> nécessite <strong>Studio 0.1.280 ou une version ultérieure</strong>. Cet ensemble de widgets autonome comprend quatre modules indépendants de toute marque, dotés de graphismes SVG transparents. Mettez d&#39;abord à jour Studio, puis importez le <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/raw/refs/heads/master/ha_grafik_visual_studio/packages/solar/ugso.solar.wg" target="_blank" rel="noreferrer">fichier de paquet ugso.solar.wg</a> via les paramètres des paquets.</p><table tabindex="0"><thead><tr><th>Widget</th><th>Taille standard</th><th>Points de connexion</th><th>Points de ligne</th></tr></thead><tbody><tr><td>Élément supérieur (pile)</td><td>256 × 64 px</td><td>En bas, au centre</td><td>À gauche/droite, ainsi que deux entrées pour panneaux solaires de chaque côté du boîtier</td></tr><tr><td>Module batterie</td><td>256 × 169 px</td><td>En haut et en bas, au centre</td><td>À gauche, à droite</td></tr><tr><td>Onduleur Solo</td><td>144 × 103,3 px</td><td>Aucune</td><td>À gauche/droite/en haut au centre, ainsi que sept points en bas, coins inclus</td></tr><tr><td>Panneau solaire avec pied</td><td>320 × 288 px</td><td>Aucune</td><td>Une sortie : au niveau du mât ou sur le bord gauche/droite du widget</td></tr></tbody></table><p>Le graphique de l&#39;élément principal est positionné au centre, sur le bord inférieur du widget. La batterie s&#39;aligne parfaitement avec le graphique, en haut comme en bas. La batterie et l&#39;onduleur Solo conservent leurs proportions lors d&#39;un agrandissement ou d&#39;une réduction. Le boîtier visible de l&#39;onduleur Solo est environ un tiers plus étroit que l&#39;élément principal.</p><p><img src="'+s+'" alt="Système solaire dans l&#39;éditeur : empilement de batteries, onduleur Solo et les deux orientations possibles pour le panneau solaire"></p><p>Exemple avec des valeurs de prévisualisation et les points de connexion affichés. Les cercles jaunes représentent les entrées, les cercles bleus les sorties, et les carrés violets les points de couplage entre boîtiers. Ces points disparaissent lors de l&#39;exécution (runtime).</p><h2 id="solarpanel-mit-standrohr-und-fuß" tabindex="-1">Panneau solaire avec mât et pied <a class="header-anchor" href="#solarpanel-mit-standrohr-und-fuß" aria-label="Permalink to &quot;Panneau solaire avec mât et pied {#solarpanel-mit-standrohr-und-fuß}&quot;">​</a></h2><p>Sous <strong>Module solaire → Orientation</strong>, vous pouvez choisir <strong>Comme le modèle</strong> ou <strong>Miroir</strong>. Le graphique SVG est alors inversé horizontalement ; le texte et l&#39;affichage des valeurs restent lisibles. Les proportions sont préservées lors du redimensionnement.</p><p><img src="'+t+'" alt="Panneau solaire avec mât et pied : à gauche identique au modèle, à droite en miroir ; sortie située sur le mât dans les deux cas"></p><p>Sélectionnez une entité Home Assistant sous <strong>Puissance → Entité d&#39;entrée (Puissance)</strong>. Les valeurs exprimées en kW sont converties en W. L&#39;option <strong>Afficher la valeur</strong> masque uniquement le texte (sans cadre) ; la sortie continue toutefois de transmettre des données. En l&#39;absence d&#39;entité, la valeur de prévisualisation est utilisée ; si l&#39;entité est inconnue, un tiret s&#39;affiche.</p><p>Sous <strong>Connexion de ligne → Position du point de départ</strong>, trois options sont disponibles : <strong>Sur le tube vertical au-dessus du pied</strong>, <strong>Bord gauche du widget</strong> et <strong>Bord droit du widget</strong>. Les positions sur les bords se situent à la même hauteur que le point sur le tube. Il n&#39;y a qu&#39;une seule sortie ; les lignes SVG déjà connectées s&#39;ajustent automatiquement en cas de modification. L&#39;option <strong>Point de départ actif</strong> permet d&#39;activer ou de désactiver ce point. En mode exécution (runtime), le point est invisible, tandis que la ligne SVG reste visible. Le panneau solaire ne dispose pas de points de connexion sur son boîtier.</p><h2 id="einen-stapel-zusammensetzen" tabindex="-1">Assembler une pile <a class="header-anchor" href="#einen-stapel-zusammensetzen" aria-label="Permalink to &quot;Assembler une pile {#einen-stapel-zusammensetzen}&quot;">​</a></h2><p>Ajoutez <strong>un élément supérieur</strong> (en-tête) ainsi que, selon votre installation, <strong>1 à 6 instances du même widget de batterie</strong>. Chaque batterie possède ses propres paramètres et entités. Les points de connexion centraux du boîtier sont activés par défaut, avec un espacement de <strong>0 px</strong>. Faites glisser une batterie en reliant son point supérieur au point inférieur de l&#39;élément supérieur ou d&#39;une autre batterie. Les éléments s&#39;alignent automatiquement de manière centrée et jointive.</p><p>Sous <strong>Points d&#39;accrochage du boîtier</strong>, vous pouvez configurer l&#39;accrochage (snapping), les points individuels, l&#39;espacement et l&#39;affichage permanent dans l&#39;éditeur. Les points de connexion du boîtier servent uniquement au positionnement ; ils ne transmettent aucune valeur. Ces points sont invisibles en mode exécution (runtime).</p><h2 id="werte-als-text-auf-dem-gehause" tabindex="-1">Valeurs affichées sous forme de texte sur le boîtier <a class="header-anchor" href="#werte-als-text-auf-dem-gehause" aria-label="Permalink to &quot;Valeurs affichées sous forme de texte sur le boîtier {#werte-als-text-auf-dem-gehause}&quot;">​</a></h2><p>Pour la <strong>puissance</strong>, la <strong>température</strong> et l&#39;<strong>état de charge (SoC)</strong>, une sélection d&#39;entité Home Assistant ainsi qu&#39;une valeur de prévisualisation sont disponibles pour chaque paramètre. Les unités utilisées sont le <strong>W</strong>, le <strong>°C</strong> et le <strong>%</strong>. La puissance issue d&#39;une entité exprimée en kW est convertie en W. La valeur de prévisualisation ne s&#39;affiche que tant qu&#39;aucune entité n&#39;est renseignée. Les états manquants ou inconnus sont représentés par <strong>—</strong>.</p><p>L&#39;option <strong>Afficher la valeur</strong> permet de désactiver uniquement l&#39;affichage textuel correspondant. L&#39;entité continue d&#39;être mise à jour et les sorties continuent de transmettre leur valeur. Dans le cas de la batterie, les indicateurs actifs s&#39;affichent juste en dessous de la ligne de séparation située après le premier tiers ; ils sont disposés automatiquement les uns en dessous des autres, sans espaces vides pour les éléments masqués. Il n&#39;y a ni cadre ni encadré d&#39;affichage. L&#39;ordre est le suivant : puissance, température, SoC. La couleur et la taille maximale de la police sont réglables ; si l&#39;espace est restreint, la taille de la police est réduite.</p><p>Par défaut, la batterie affiche les trois valeurs, tandis que le modèle « Solo » n&#39;affiche que la puissance. L&#39;en-tête n&#39;affiche aucune valeur et ne propose pas de regroupement pour la puissance, la température, le SoC ou le sens du flux de puissance. Ces paramètres sont conservés pour l&#39;onduleur « Solo ».</p><p>Pour la batterie, il est possible de définir séparément la <strong>couleur de la police</strong> des valeurs affichées pour la <strong>puissance</strong>, la <strong>température</strong> et l&#39;<strong>état de charge (SoC)</strong>. Si aucune couleur spécifique n&#39;est définie, la couleur de police générale s&#39;applique. La couleur est conservée même lorsque l&#39;affichage est masqué puis réaffiché.</p><p><img src="'+n+'" alt="En-tête empilable avec quatre entrées pour panneaux solaires et une batterie affichant des valeurs en couleur, ainsi que des points de connexion latéraux sur le bord inférieur"></p><p>Dans la section <strong>Sens de la puissance</strong>, vous pouvez activer un symbole directionnel. Définissez si une puissance positive correspond à un <strong>flux d&#39;énergie entrant</strong> ou <strong>sortant</strong>, et choisissez les symboles correspondants via des champs de saisie de texte libre. En cas de puissance nulle ou de valeur inconnue, aucun symbole directionnel n&#39;est affiché. Le signe de la valeur numérique est conservé.</p><h2 id="ein-und-ausgange-fur-svg-linien" tabindex="-1">Entrées et sorties pour les lignes SVG <a class="header-anchor" href="#ein-und-ausgange-fur-svg-linien" aria-label="Permalink to &quot;Entrées et sorties pour les lignes SVG {#ein-und-ausgange-fur-svg-linien}&quot;">​</a></h2><p>L&#39;<strong>onduleur « Solo »</strong> dispose, sur son bord inférieur, de sept points de connexion répartis uniformément : les deux coins, le point central (existant précédemment) et deux points supplémentaires de chaque côté de celui-ci. En incluant les points situés au centre des côtés gauche, droit et supérieur, on obtient un total de dix points de connexion. Dans la section <strong>Connexions de lignes</strong>, vous pouvez définir, pour chaque point, s&#39;il s&#39;agit d&#39;une <strong>entrée</strong> ou d&#39;une <strong>sortie</strong> (ou s&#39;il est <strong>désactivé</strong>), et spécifier la valeur associée. Les six nouveaux points situés en bas sont désactivés par défaut ; les connexions et liaisons déjà existantes restent inchangées.</p><p><img src="'+r+'" alt="Onduleur « Solo » avec sept points de connexion sur le bord inférieur et trois points supplémentaires situés à gauche, à droite et en haut"></p><p>Dans cet exemple, les dix points sont configurés comme sorties ; dans votre propre projet, vous pouvez choisir le rôle de chaque point individuellement.</p><p>Pour la batterie, une <strong>position</strong> supplémentaire est disponible à gauche et à droite : <strong>bord central du widget</strong> ou <strong>bord du boîtier au niveau de la jointure inférieure</strong>. Les deux côtés peuvent être configurés indépendamment. Les connexions existantes sont conservées ; le rôle (entrée/sortie) et l&#39;affectation des valeurs restent inchangés. Les points de connexion centraux du boîtier (en haut et en bas), utilisés pour l&#39;empilement, ne sont pas affectés par ce changement.</p><p>L&#39;élément supérieur (tête) dispose de quatre connecteurs visuels pour panneaux solaires : en haut et en bas, à gauche comme à droite. Ces quatre entrées sont actives par défaut et peuvent être désactivées individuellement dans la section <strong>Connexions de lignes</strong>. Elles suivent le tracé graphique aligné sur la partie inférieure, quelle que soit la hauteur du widget. Reliez la ligne SVG d&#39;un panneau solaire à l&#39;un de ces connecteurs. Les entrées constituent des cibles de ligne distinctes ; les valeurs ne sont pas additionnées automatiquement. L&#39;ancien point de connexion supérieur est supprimé, tandis que les points de connexion situés à gauche et à droite restent disponibles.</p><p>Dans la section <strong>Connexions de lignes</strong>, chaque côté disponible propose deux réglages :</p><ul><li><strong>Rôle :</strong> Désactivé, Entrée ou Sortie. Par défaut, les points de connexion sont désactivés.</li><li><strong>Valeur :</strong> Puissance, Température ou État de charge (SoC).</li></ul><p>Une <strong>sortie</strong> transmet la valeur sélectionnée, accompagnée de son unité, par exemple vers un élément <em>Number</em> ou une ligne SVG. Une <strong>entrée</strong> récupère cette valeur depuis une source unique connectée et remplace l&#39;entité pour ce canal. N&#39;utilisez qu&#39;une seule entrée par valeur. Une autre sortie peut relayer la valeur ainsi récupérée ; les boucles de rétroaction sont gérées (interceptées). Aucune entité Home Assistant n&#39;est modifiée.</p><p>Les points de ligne sont indépendants des points de connexion du boîtier. Les sorties actives utilisent la couleur définie pour les points de sortie dans les paramètres du Studio. En mode exécution (<em>runtime</em>), ces points disparaissent ; les lignes SVG classiques restent visibles, tandis que les connexions de valeurs demeurent invisibles.</p><p>Tous les groupes CSS standard sont disponibles ; les sections optionnelles sont désactivées par défaut. L&#39;ajout de marges internes (<em>padding</em>) ou de bordures peut altérer l&#39;alignement affleurant.</p><p>Les éléments SVG sont des graphismes UGSo spécifiques, dépourvus de logo de fabricant. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/ha_grafik_visual_studio/packages/solar" target="_blank" rel="noreferrer">Code source, instructions de montage et licence MIT</a>.</p>',33)])])}const x=i(l,[["render",d]]);export{b as __pageData,x as default};
